public class Tier {
    // Attribute
    private String name;
    private int alter;

    // Konstruktor
    public Tier(String nameStart, int alterStart) {
        name = nameStart;
        alter = alterStart;
    }

    // eigene Methode
    public void fressen() {
        System.out.println(name + " frisst.");
    }
}

public class Hund extends Tier {
    // Konstruktor
    public Hund(String nameStart, int alterStart) {
        super(nameStart, alterStart);
    }

    // eigene Methode
    public void bellen() {
        System.out.println("Wuff!");
    }
}

public class Tierheim {
    public static void main(String[] args) {
        Hund bello = new Hund("Bello", 3);
        Katze mimi = new Katze("Mimi", 2);
        bello.fressen();
        bello.bellen();
        mimi.fressen();
        mimi.miauen();
    }
}

public class Hund extends Tier {
    // Konstruktor
    public Hund(String nameStart, int alterStart) {
        super(nameStart, alterStart);
    }

    // Methode überschreiben
    @Override
    public void fressen() {
        System.out.println("Bello schlingt sein Futter.");
    }
}

public class Katze extends Tier {
    // Konstruktor
